{
  "name": "@molecule/api-agent-transcript-opencode",
  "version": "1.0.2",
  "description": "Reads OpenCode session exports (opencode export) into a normalized agent session",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "keywords": [
    "molecule",
    "agent",
    "transcript",
    "opencode",
    "export",
    "session"
  ],
  "license": "Apache-2.0",
  "author": "Molecule Dev, Inc. (https://molecule.dev)",
  "peerDependencies": {
    "@molecule/api-agent-transcript": "^1.0.0"
  },
  "devDependencies": {
    "@molecule/api-agent-transcript": "1.0.2",
    "@types/node": "26.6.5",
    "typescript": "6.0.3",
    "vitest": "4.1.12"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/molecule-dev/molecule.git",
    "directory": "packages/api/bonds/agent-transcript/opencode"
  },
  "homepage": "https://www.molecule.dev/packages/api-agent-transcript-opencode",
  "bugs": "https://github.com/molecule-dev/molecule/issues",
  "publishConfig": {
    "access": "public"
